// Bleistift-Skizze (XDoG-Idee): Difference-of-Gaussians auf der Helligkeit
// als weicher Strich, Papierkorn aus einem Positions-Hash (deterministisch).
float lum(vec2 p) { return dot(texture(uTex, p).rgb, vec3(0.299, 0.587, 0.114)); }
float blur(vec2 uv, float r)
{
    vec2 px = r / uResolution;
    float s = lum(uv) * 4.0;
    s += lum(uv + vec2(px.x, 0.0)) * 2.0 + lum(uv - vec2(px.x, 0.0)) * 2.0;
    s += lum(uv + vec2(0.0, px.y)) * 2.0 + lum(uv - vec2(0.0, px.y)) * 2.0;
    s += lum(uv + px) + lum(uv - px) + lum(uv + vec2(px.x, -px.y)) + lum(uv + vec2(-px.x, px.y));
    return s / 16.0;
}
vec4 farbe(vec2 uv, vec4 src)
{
    float fein = blur(uv, 1.0);
    float grob = blur(uv, 2.5);
    float dog = fein - grob;
    float strich = 1.0 - smoothstep(0.0, 0.012 + 0.01 * bass, dog);
    float schatten = smoothstep(0.75, 0.15, fein) * 0.35;
    float korn = fract(sin(dot(floor(uv * uResolution * 0.5), vec2(12.9898, 78.233))) * 43758.5453);
    vec3 papier = vec3(0.96, 0.95, 0.91) - korn * 0.03;
    vec3 grafit = vec3(0.22, 0.22, 0.26);
    return vec4(mix(papier, grafit, clamp(strich * 0.85 + schatten, 0.0, 1.0)), 1.0);
}
